parameters.jsCode:
const body = $input.item.json.body;

const ids = body.all_dispatch_ids.split(',');
const equipments = body.equipment_list.split(',');
const rates = body.vendor_base_rate.split(',');

return ids.map((id, i) => ({
  json: {
    dispatch_id: id.trim(),
    equipment: equipments[i] ? equipments[i].trim() : '',
    vendor_rate: parseFloat(rates[i]) || 0,
    dispatch_status: body.dispatch_status,
    customer_name: body.customer_name,
    customer_email: body.customer_email,
    customer_phone: body.customer_phone,
    vendor_name: body.vendor_name,
    vendor_phone: body.vendor_phone,
    vendor_email: body.vendor_email,
    city: body.city,
    start_date: body.start_date,
    end_date: body.end_date,
    all_dispatch_ids: body.all_dispatch_ids,
    vendor_priority: body.vendor_priority
  }
}));

// 1. Equipment ki list pichle node se le rahe hain
const allItems = $('Edit Fields').all();

// 2. Customer aur Vendor ki info seedha Webhook se le rahe hain
// (Note: Agar field names Webhook mein thore alag hain toh wo check kar lein)
const webhook = $('Webhook').item.json.body;

return [{
  json: {
    // Customer Details (Webhook se)
    customer_name: webhook.customer_name || allItems[0].json.customer_name,
    customer_email: webhook.customer_email || 'N/A',
    customer_phone: webhook.customer_phone || 'N/A',
    city: webhook.city || 'N/A', // Aap ne kaha city simple hai

    // Vendor Details (Webhook se)
    vendor_name: webhook.vendor_name || 'N/A',
    vendor_phone: webhook.vendor_phone || 'N/A',
    vendor_email: webhook.vendor_email || 'N/A',

    // Dates (Webhook se)
    start_date: webhook.start_date,
    end_date: webhook.end_date,

    // Aggregated List (Jo humne pehle banayi thi)
    all_dispatch_ids: allItems.map(i => i.json.dispatch_id).join(", "),
    equipment_list: allItems.map(i => i.json),
    status: allItems[0].json.dispatch_status || "Available"
  }
}];
